#!/usr/bin/env bash
set -euo pipefail
re_root=/home/john/Desktop/cheat_re
re_sysroot="$re_root/dump_analysis/semantic_reconstruction/toolchain"
re_out="$re_root/dump_analysis/semantic_reconstruction/world_esp"
re_extra=()
if [[ "${RE_ANALYSIS_SANITIZE:-0}" == 1 ]]; then
re_extra+=(-fsanitize=address,undefined -static-libasan -static-libubsan -fno-sanitize-recover=all -fno-omit-frame-pointer)
fi
"$re_sysroot/usr/bin/x86_64-linux-gnu-g++-15" --sysroot="$re_sysroot" -B"$re_sysroot/usr/lib/gcc/x86_64-linux-gnu/15/" -B"$re_sysroot/usr/libexec/gcc/x86_64-linux-gnu/15/" -L/usr/lib/x86_64-linux-gnu -std=c++20 -Wall -Wextra -Wpedantic -Werror -D_GLIBCXX_ASSERTIONS -ffp-contract=off -O1 -g "${re_extra[@]}" -I"$re_root/source/reconstructed" "$re_root/source/reconstructed/04_esp_entities.cpp" "$re_root/source/reconstructed/05_server_observable.cpp" "$re_root/source/reconstructed/world_esp_analysis.cpp" "$re_root/source/reconstructed/world_esp_classifier_tables.cpp" "$re_root/source/reconstructed/world_esp_draw_tables.cpp" "$re_root/source/reconstructed/world_esp_draw.cpp" "$re_root/source/reconstructed/world_esp_labels.cpp" "$re_root/source/reconstructed/world_esp_overlay.cpp" "$re_root/source/reconstructed/world_esp_overlay_worker.cpp" "$re_root/source/reconstructed/world_esp_overlay_controls.cpp" "$re_root/source/reconstructed/world_esp_overlay_aux.cpp" "$re_root/source/reconstructed/world_esp_overlay_tail.cpp" "$re_root/source/reconstructed/world_esp_grid.cpp" "$re_root/source/reconstructed/world_esp_status.cpp" "$re_root/source/reconstructed/world_esp_sign_status.cpp" "$re_root/source/reconstructed/world_esp_windows.cpp" "$re_root/source/reconstructed/world_esp_simulation.cpp" "$re_root/source/reconstructed/world_esp_simulation_worker.cpp" "$re_root/source/reconstructed/world_esp_players.cpp" "$re_root/source/reconstructed/world_esp_player_actions.cpp" "$re_root/source/reconstructed/world_esp_player_worker.cpp" "$re_root/source/reconstructed/world_esp_inventory_tooltip.cpp" "$re_root/source/reconstructed/world_esp_skeleton_tables.cpp" "$re_root/source/reconstructed/world_esp_player_radar.cpp" "$re_root/source/reconstructed/world_esp_player_labels.cpp" "$re_root/source/reconstructed/world_esp_category_data.cpp" "$re_root/source/reconstructed/world_esp_cached.cpp" "$re_root/source/reconstructed/world_esp_bounds.cpp" "$re_root/source/reconstructed/world_esp_names.cpp" "$re_root/source/reconstructed/world_esp_item_names.cpp" "$re_root/source/reconstructed/world_esp_turret.cpp" "$re_root/source/reconstructed/world_esp_dropped.cpp" "$re_root/source/reconstructed/world_esp_interaction.cpp" "$re_root/source/reconstructed/world_esp_fishing.cpp" "$re_root/source/reconstructed/world_esp_worker.cpp" "$re_root/source/reconstructed/world_esp_owner_data.cpp" "$re_root/source/reconstructed/world_esp_coverage.cpp" "$re_root/source/reconstructed/world_esp_checks.cpp" "$re_root/source/reconstructed/world_esp_extended_checks.cpp" "$re_out/check_main.cpp" -o "$re_out/world_esp_checks${RE_ANALYSIS_SANITIZE:-0}"
"$re_out/world_esp_checks${RE_ANALYSIS_SANITIZE:-0}"
